-- =============================================================================
-- Backfill: sube a produccion el trabajo hecho en local a partir de las fichas
-- de Dropbox (catastro, CIF, CP, administrador, presidentes y la bitacora de
-- observaciones).
--
-- Local y remoto se poblaron por separado desde Monday y los UUID NO coinciden,
-- asi que NADA se casa por id: se traduce con `migracion_monday.monday_item_id`,
-- que es el mismo en los dos. Lo que no viene de Monday se casa por nombre
-- exacto (lo genero el mismo importador, es identico).
--
-- Idempotente: aplicarlo dos veces no duplica ni pisa dato existente.
-- =============================================================================

create temp table _com (local_id uuid, monday_item_id text, nombre text, direccion text,
                        municipio text, catastral text, cif text, cp text,
                        admin_monday text, admin_nombre text);

create temp table _adm (local_id uuid, monday_item_id text, nombre text, email text,
                        telefono text, direccion text, municipio text);

create temp table _con (admin_monday text, admin_nombre text, nombre text, telefono text,
                        email text, proposito text, notas text);

create temp table _per (local_com uuid, monday_item_id text, com_nombre text, com_direccion text,
                        nombre text, rol text, documento text, telefono text,
                        email text);

create temp table _obs (local_com uuid, monday_item_id text, com_nombre text, com_direccion text,
                        proy_monday text, fecha date, estimada boolean, orden int,
                        texto text, fase text, origen text, ficha_ref text);

-- ---- traduccion de ids ----
-- Dos estrategias EXPLICITAS y en este orden, nunca una al azar:
--   1. por monday_item_id, que es el mismo en los dos lados (exacto)
--   2. si no viene de Monday, por nombre+direccion y SOLO si hay una unica
--      candidata; si hay varias se descarta, no se elige.
create temp table _mapcom_bruto as
select t.local_id, m.registro_id remote_id, 'monday' via
  from _com t join migracion_monday m
    on m.tabla_destino = 'comunidades' and m.monday_item_id = t.monday_item_id
 where t.monday_item_id <> ''
union all
select t.local_id, c.id, 'texto'
  from _com t join comunidades c
    on coalesce(c.nombre,'') = t.nombre and coalesce(c.direccion,'') = t.direccion
 where t.monday_item_id = ''
   and (select count(*) from comunidades c2
         where coalesce(c2.nombre,'') = t.nombre
           and coalesce(c2.direccion,'') = t.direccion) = 1;

-- guarda: si un id local acaba apuntando a dos remotos, se queda fuera
create temp table _mapcom as
select local_id, min(remote_id::text)::uuid remote_id from _mapcom_bruto
 group by local_id having count(distinct remote_id) = 1;

-- lo mismo para las administraciones
create temp table _mapadm as
select local_id, min(remote_id::text)::uuid remote_id from (
  select t.local_id, m.registro_id remote_id
    from _adm t join migracion_monday m
      on m.tabla_destino = 'administraciones_fincas' and m.monday_item_id = t.monday_item_id
   where t.monday_item_id <> ''
  union all
  select t.local_id, a.id
    from _adm t join administraciones_fincas a on upper(a.nombre) = upper(t.nombre)
   where t.monday_item_id = ''
     and (select count(*) from administraciones_fincas a2
           where upper(a2.nombre) = upper(t.nombre)) = 1) x
 group by local_id having count(distinct remote_id) = 1;

-- ---- administraciones nuevas (las que no existen ni por Monday ni por nombre) ----
select t.nombre, nullif(t.email,''), nullif(t.telefono,''), nullif(t.direccion,''),
       nullif(t.municipio,'')
  from _adm t
 where not exists (select 1 from _mapadm x where x.local_id = t.local_id)
   and not exists (select 1 from administraciones_fincas a
                    where upper(a.nombre) = upper(t.nombre));

-- las recien creadas tambien entran en el mapa
select t.local_id, a.id from _adm t join administraciones_fincas a
    on upper(a.nombre) = upper(t.nombre)
 where not exists (select 1 from _mapadm x where x.local_id = t.local_id)
   and (select count(*) from administraciones_fincas a2
         where upper(a2.nombre) = upper(t.nombre)) = 1;

-- ---- rellenar huecos de las administraciones (nunca pisar lo que ya hay) ----
update administraciones_fincas a set
  email     = coalesce(nullif(a.email,''), nullif(t.email,'')),
  telefono  = coalesce(nullif(a.telefono,''), nullif(t.telefono,'')),
  direccion = coalesce(nullif(a.direccion,''), nullif(t.direccion,''))
  from _adm t join _mapadm mm on mm.local_id = t.local_id
 where a.id = mm.remote_id
   and (a.email is null or a.email = '' or a.telefono is null or a.telefono = ''
        or a.direccion is null or a.direccion = '');

-- ---- comunidades: catastro, CIF, CP y administrador (solo si estan vacios) ----
update comunidades c set
  referencia_catastral = coalesce(nullif(c.referencia_catastral,''), nullif(t.catastral,'')),
  cif_comunidad        = coalesce(nullif(c.cif_comunidad,''), nullif(t.cif,'')),
  cp                   = coalesce(nullif(c.cp,''), nullif(t.cp,'')),
  administracion_id    = coalesce(c.administracion_id, ma.remote_id)
  from _com t
  join _mapcom mm on mm.local_id = t.local_id
  left join _adm ta on upper(ta.nombre) = upper(nullif(t.admin_nombre,''))
  left join _mapadm ma on ma.local_id = ta.local_id
 where c.id = mm.remote_id
   and (c.referencia_catastral is null or c.referencia_catastral = ''
        or c.cif_comunidad is null or c.cif_comunidad = ''
        or c.cp is null or c.cp = '' or c.administracion_id is null);

-- ---- contactos nuevos ----
select ma.remote_id, t.nombre, nullif(t.telefono,''), nullif(t.email,''),
       t.proposito, nullif(t.notas,'')
  from _con t
  join _adm ta on upper(ta.nombre) = upper(t.admin_nombre)
  join _mapadm ma on ma.local_id = ta.local_id
 where not exists (select 1 from contactos c where c.administracion_id = ma.remote_id
                     and upper(c.nombre) = upper(t.nombre));

-- ---- presidentes ----
select mm.remote_id, t.nombre, t.rol, nullif(t.documento,''), nullif(t.telefono,''),
       nullif(t.email,'')
  from _per t join _mapcom mm on mm.local_id = t.local_com
 where not exists (select 1 from personas_comunidad p where p.comunidad_id = mm.remote_id
                     and upper(p.nombre) = upper(t.nombre));

-- ---- observaciones (la bitacora) ----
select mm.remote_id,
       (select m.registro_id from migracion_monday m where m.tabla_destino='proyectos'
         and m.monday_item_id = nullif(t.proy_monday,'') limit 1),
       t.fase, t.fecha, t.estimada, t.orden, t.texto, t.origen, nullif(t.ficha_ref,'')
  from _obs t join _mapcom mm on mm.local_id = t.local_com
 where not exists (select 1 from observaciones_expediente o
                    where o.comunidad_id = mm.remote_id and o.texto = t.texto);
